-- Disposable local rehearsal: production column metadata, NO production rows. Enums represented as text; unrelated helpers stubbed in test harness.
CREATE TABLE public.endurance_events ("id" uuid,"name" text,"circuit" text,"configuration" text,"image_url" text,"start_at" timestamp with time zone,"end_at" timestamp with time zone,"briefing_start_at" timestamp with time zone,"expected_end_at" timestamp with time zone,"registration_deadline" timestamp with time zone,"slots" jsonb,"class_ids" text[],"selected_class_id" text,"selected_car_id" text,"max_drivers_per_car" integer,"visibility" text,"status" text,"source" text,"invited_user_ids" uuid[],"manager_ids" uuid[],"race_id" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"iracing_catalog_event_id" uuid,"iracing_catalog_slot_id" uuid,"iracing_source_key" text,"iracing_source_hash" text,"iracing_slot_key" text,"iracing_imported_at" timestamp with time zone,"allowed_car_ids" text[],"planned_laps" integer,"planned_duration_minutes" integer,"race_distance_source" text,PRIMARY KEY (id));
