CREATE TABLE public.endurance_practice_laps ("id" uuid,"session_id" uuid,"event_id" uuid,"user_id" uuid,"car_id" text,"circuit" text,"lap_seconds" numeric,"fuel_used_litres" numeric,"fuel_per_lap_litres" numeric,"incident_count" smallint,"recorded_at" timestamp with time zone,"source_session_id" text,"source_device_id" uuid,"completed_laps" integer,"car_name" text,PRIMARY KEY (id));
CREATE TABLE public.endurance_practice_sessions ("id" uuid,"event_id" uuid,"team_id" uuid,"label" text,"started_at" timestamp with time zone,"ended_at" timestamp with time zone,"requires_registered" boolean,"created_by" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"car_id" text,"circuit" text,"configuration" text,"conditions" text,PRIMARY KEY (id));
